import re
from datetime import date, datetime
from calendar import monthrange
from dateutil import parser as dp

def _d(v, name):
    try:
        return dp.parse(str(v)).date()
    except Exception:
        raise ValueError(f'invalid date in {name}: {v!r}')

def _digits(s):
    return re.sub(r'\D', '', str(s or '')).lstrip('0')

def _num(v):
    if isinstance(v, (int, float)):
        return float(v)
    try:
        return float(str(v).replace(' ', '').replace('\xa0', '').replace(',', '.'))
    except Exception:
        return 0.0

def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    for k in ('supplier_invoices', 'bank_transactions', 'customer_invoices'):
        if not isinstance(inp.get(k), list):
            raise ValueError(f'{k} must be a list')
    asof = _d(inp['as_of_date'], 'as_of_date') if inp.get('as_of_date') else date.today()
    tm = inp.get('target_month')
    if tm:
        if not re.fullmatch(r'\d{4}-\d{2}', str(tm)) or not 1 <= int(str(tm)[5:]) <= 12:
            raise ValueError('target_month must be YYYY-MM')
        ty, tmo = int(tm[:4]), int(tm[5:])
    else:
        ty, tmo = (asof.year + (asof.month == 12), asof.month % 12 + 1)
    mstart = date(ty, tmo, 1)
    mend = date(ty, tmo, monthrange(ty, tmo)[1])
    focus = str(inp.get('focus') or 'all').lower()
    skipped = []
    bank = []
    for i, t in enumerate(inp['bank_transactions']):
        try:
            bank.append(dict(i=i, id=f'bank:{i}', date=_d(t['date'], 'bank'), amt=_num(t.get('amount')), vs=_digits(t.get('variable_symbol')), cp=str(t.get('counterparty') or ''), bal=t.get('balance')))
        except Exception as e:
            skipped.append(f'bank:{i}: {e}')
    opening = 0.0
    dated = [b for b in bank if b['bal'] is not None]
    if dated:
        opening = _num(max(dated, key=lambda b: (b['date'], b['i']))['bal'])
    overdue, inflows, outflows = [], [], []
    if focus in ('all', 'receivables', 'inflows'):
        for c in inp['customer_invoices']:
            try:
                num = c.get('invoice_number')
                due = _d(c['due_date'], 'due_date')
                amt = _num(c.get('amount_czk', c.get('total')))
                key = _digits(num)
                ms = [b for b in bank if b['amt'] > 0 and key and b['vs'] == key]
                paid = sum(b['amt'] for b in ms)
                rem = round(amt - paid, 2)
                if rem <= 0.01:
                    continue
                rec = dict(invoice_number=num, customer=c.get('customer'), due_date=str(due), amount=amt, paid=round(paid, 2), outstanding=rem, record_ids=[str(num)] + [b['id'] for b in ms])
                if due < asof:
                    rec['days_overdue'] = (asof - due).days
                    overdue.append(rec)
                elif due <= mend:
                    rec['expected_date'] = str(due)
                    inflows.append(rec)
            except Exception as e:
                skipped.append(f'customer_invoice {c.get("invoice_number") if isinstance(c, dict) else c}: {e}')
    paidvs = set()
    if focus in ('all', 'payables', 'outflows'):
        outs = [b for b in bank if b['amt'] < 0]
        for s in inp['supplier_invoices']:
            try:
                key = _digits(s.get('vs'))
                due = _d(s['due_date'], 'due_date')
                tot = _num(s.get('total'))
                ms = [b for b in outs if key and b['vs'] == key]
                if key:
                    paidvs.add(key)
                paid = -sum(b['amt'] for b in ms)
                rem = round(tot - paid, 2)
                if rem <= 0.01 or due > mend:
                    continue
                outflows.append(dict(type='supplier_invoice', supplier=s.get('supplier'), invoice_number=s.get('invoice_number'), due_date=str(due), amount=rem, overdue=due < asof, record_ids=[str(s.get('invoice_number'))] + [b['id'] for b in ms]))
            except Exception as e:
                skipped.append(f'supplier_invoice {s.get("invoice_number") if isinstance(s, dict) else s}: {e}')
        groups = {}
        for b in outs:
            if b['vs'] in paidvs and b['vs']:
                continue
            groups.setdefault((b['cp'], round(b['amt'])), []).append(b)
        for (cp, a), g in groups.items():
            months = {(b['date'].year, b['date'].month) for b in g}
            if len(months) >= 2:
                outflows.append(dict(type='recurring_bank_outflow', counterparty=cp, amount=round(-g[0]['amt'], 2), expected_month=f'{ty:04d}-{tmo:02d}', occurrences=len(g), record_ids=[b['id'] for b in g]))
    tin = round(sum(r['outstanding'] for r in inflows), 2)
    tout = round(sum(r['amount'] for r in outflows), 2)
    net = round(tin - tout, 2)
    tod = round(sum(r['outstanding'] for r in overdue), 2)
    summary = f'ESTIMATE for {ty:04d}-{tmo:02d} as of {asof}: expected inflows {tin}, outflows {tout}, net exposure {net}; opening balance {opening}; {len(overdue)} overdue receivables totalling {tod} (not counted in inflows).'
    if skipped:
        summary += f' Skipped {len(skipped)} unparseable records.'
    return dict(overdue_receivables=overdue, expected_inflows=inflows, expected_outflows=outflows, net_exposure_estimate=net, opening_balance=opening, total_overdue_receivables=tod, skipped=skipped, is_estimate=True, summary=summary)

