import re
from datetime import date, datetime

def _d(s):
    try:
        return datetime.strptime(str(s)[:10], '%Y-%m-%d').date()
    except Exception:
        return None

def _digits(s):
    return re.sub(r'\D', '', str(s or ''))

def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    for k in ('supplier_invoices', 'bank_transactions', 'customer_invoices'):
        if not isinstance(inp.get(k), list):
            raise ValueError(k + ' must be a list')
    tm = str(inp.get('target_month') or '')
    if not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])', tm):
        raise ValueError('target_month must be YYYY-MM')
    if inp.get('as_of_date'):
        asof = _d(inp['as_of_date'])
        if not asof:
            raise ValueError('as_of_date must be YYYY-MM-DD')
    else:
        asof = date.today()
    bank = [b for b in inp['bank_transactions'] if isinstance(b, dict)]
    skipped = []
    used = set()

    def paid(ref, vs, sign):
        rd, vd = _digits(ref), _digits(vs)
        for i, b in enumerate(bank):
            if i in used:
                continue
            try:
                amt = float(b.get('amount') or 0)
            except Exception:
                continue
            if amt * sign <= 0:
                continue
            bv = _digits(b.get('variable_symbol'))
            msg = str(b.get('message') or '')
            if (bv and (bv == rd or bv == vd) and bv) or (ref and str(ref) in msg):
                used.add(i)
                return True
        return False

    overdue, inflows, outflows, carried = [], [], [], []
    for c in inp['customer_invoices']:
        dd = _d(c.get('due_date')) if isinstance(c, dict) else None
        if not dd:
            skipped.append({'record': str(c)[:80], 'reason': 'bad customer invoice'})
            continue
        if paid(c.get('invoice_number'), None, 1):
            continue
        rec = {'id': c.get('invoice_number'), 'party': c.get('customer'), 'due_date': str(dd), 'amount': float(c.get('amount_czk') or 0), 'direction': 'inflow'}
        if dd < asof:
            overdue.append(dict(rec, days_overdue=(asof - dd).days))
        if dd.strftime('%Y-%m') == tm:
            inflows.append(dict(rec, type='customer_invoice'))
        elif dd.strftime('%Y-%m') < tm:
            carried.append(dict(rec, label='unpaid, due before target month; not in net estimate'))
    for s in inp['supplier_invoices']:
        dd = _d(s.get('due_date')) if isinstance(s, dict) else None
        if not dd:
            skipped.append({'record': str(s)[:80], 'reason': 'bad supplier invoice'})
            continue
        if paid(s.get('invoice_number'), s.get('vs'), -1):
            continue
        rec = {'id': s.get('invoice_number'), 'party': s.get('supplier'), 'due_date': str(dd), 'amount': float(s.get('total') or 0), 'direction': 'outflow'}
        if dd.strftime('%Y-%m') == tm:
            outflows.append(dict(rec, type='supplier_invoice'))
        elif dd.strftime('%Y-%m') < tm:
            carried.append(dict(rec, label='unpaid, due before target month; not in net estimate'))
    groups = {}
    for i, b in enumerate(bank):
        d = _d(b.get('date'))
        try:
            a = float(b.get('amount'))
        except Exception:
            continue
        if a >= 0 or not d or i in used or d.strftime('%Y-%m') >= tm:
            continue
        k = (b.get('counterparty'), b.get('message'), a)
        groups.setdefault(k, []).append(d)
    for (cp, msg, a), ds in groups.items():
        if len({x.strftime('%Y-%m') for x in ds}) >= 2:
            outflows.append({'id': 'recurring:' + str(cp), 'party': cp, 'description': msg, 'amount': -a, 'direction': 'outflow', 'type': 'recurring', 'last_seen': str(max(ds))})
    opening = 0.0
    dated = sorted([b for b in bank if _d(b.get('date')) and _d(b.get('date')) <= asof and b.get('balance') is not None], key=lambda b: _d(b['date']))
    if dated:
        opening = float(dated[-1]['balance'])
    tin = sum(x['amount'] for x in inflows)
    tout = sum(x['amount'] for x in outflows)
    net = round(tin - tout, 2)
    tov = sum(x['amount'] for x in overdue)
    cs = sum(x['amount'] for x in carried if x['direction'] == 'outflow')
    summary = ('Estimated net cash flow for %s (inflows %.2f minus outflows %.2f, only items due in that month): %.2f. Overdue receivables as of %s: %d totalling %.2f. Earlier-month unpaid items reported separately (%d, payables %.2f), not included in net.' % (tm, tin, tout, net, asof, len(overdue), tov, len(carried), cs))
    out = {'overdue_receivables': overdue, 'expected_inflows': inflows, 'expected_outflows': outflows, 'carried_over_before_target_month': carried, 'net_exposure_estimate': net, 'opening_balance': opening, 'summary': summary}
    if skipped:
        out['skipped_records'] = skipped
    return out

