import re
from datetime import date, timedelta
from statistics import median


def _d(s, name):
    try:
        return date.fromisoformat(str(s)[:10])
    except Exception:
        raise ValueError(f'{name} must be an ISO date YYYY-MM-DD, got {s!r}')


def _digits(s):
    return re.sub(r'\D', '', str(s or ''))


def _num(x):
    try:
        return float(x)
    except Exception:
        return None


def run(inp):
    if not isinstance(inp, dict):
        raise ValueError('input must be an object')
    for k in ('supplier_invoices', 'bank_transactions', 'customer_invoices'):
        if not isinstance(inp.get(k), list):
            raise ValueError(f'{k} must be a list')
    as_of = _d(inp.get('as_of_date'), 'as_of_date')
    tm = str(inp.get('target_month') or '')
    if not re.fullmatch(r'\d{4}-\d{2}', tm) or not 1 <= int(tm[5:]) <= 12:
        raise ValueError('target_month must be YYYY-MM')
    ms = date(int(tm[:4]), int(tm[5:]), 1)
    me = (ms.replace(day=28) + timedelta(days=4)).replace(day=1) - timedelta(days=1)
    notes = []
    bank = []
    for t in inp['bank_transactions']:
        try:
            bank.append((_d(t.get('date'), 'bank date'), float(t.get('amount')), t))
        except Exception:
            notes.append(f'Skipped unparsable bank transaction: {str(t)[:80]}')
    bank.sort(key=lambda x: x[0])
    used = set()

    def match(ref, vs, amount, sign):
        for i, (d, a, t) in enumerate(bank):
            if i in used or a * sign <= 0:
                continue
            tv = _digits(t.get('variable_symbol'))
            msg = str(t.get('message') or '')
            hit = (vs and tv == vs) or (ref and ref in msg) or (ref and ref in tv and tv)
            if hit:
                used.add(i)
                return d
        return None

    rec_paid, lags_in, unpaid_r = [], [], []
    for c in inp['customer_invoices']:
        try:
            due = _d(c.get('due_date'), 'due_date')
            amt = float(c.get('amount_czk', c.get('total')))
        except Exception as e:
            notes.append(f'Skipped customer invoice {c.get("invoice_number")}: {e}')
            continue
        pd = match(str(c.get('invoice_number') or ''), _digits(c.get('invoice_number')), amt, 1)
        if pd:
            lags_in.append((pd - due).days)
        else:
            unpaid_r.append((c, due, amt))
    lags_out, unpaid_p = [], []
    for s in inp['supplier_invoices']:
        try:
            due = _d(s.get('due_date'), 'due_date')
            amt = float(s.get('total'))
        except Exception as e:
            notes.append(f'Skipped supplier invoice {s.get("invoice_number")}: {e}')
            continue
        pd = match(str(s.get('invoice_number') or ''), _digits(s.get('vs')), amt, -1)
        if pd:
            lags_out.append((pd - due).days)
        else:
            unpaid_p.append((s, due, amt))
    lin = round(median(lags_in)) if lags_in else 0
    lout = round(median(lags_out)) if lags_out else 0
    overdue, nyd, inflows = [], [], []
    for c, due, amt in unpaid_r:
        base = {'invoice_number': c.get('invoice_number'), 'customer': c.get('customer'), 'due_date': due.isoformat(), 'amount': amt}
        exp = max(due + timedelta(days=lin), as_of)
        if due < as_of:
            overdue.append({**base, 'days_overdue': (as_of - due).days})
            status = 'overdue'
        else:
            nyd.append({**base, 'days_until_due': (due - as_of).days})
            status = 'not_yet_due'
        if exp <= me:
            inflows.append({**base, 'status': status, 'expected_date': max(exp, ms).isoformat(), 'amount': amt})
    outflows, payables = [], []
    for s, due, amt in unpaid_p:
        exp = max(due + timedelta(days=lout), as_of)
        inc = exp <= me
        base = {'invoice_number': s.get('invoice_number'), 'supplier': s.get('supplier'), 'due_date': due.isoformat(), 'amount': amt,
                'status': 'overdue' if due < as_of else 'not_yet_due', 'expected_payment_date': max(exp, ms).isoformat() if inc else exp.isoformat(), 'in_target_month': inc}
        payables.append(base)
        if inc:
            outflows.append({**base, 'type': 'supplier_invoice'})
    groups = {}
    for i, (d, a, t) in enumerate(bank):
        if a < 0 and i not in used:
            groups.setdefault(str(t.get('counterparty') or 'unknown'), []).append((d, a))
    for cp, v in groups.items():
        months = {(d.year, d.month) for d, _ in v}
        amt = abs(median(a for _, a in v))
        outflows.append({'type': 'recurring', 'counterparty': cp, 'amount': round(amt, 2), 'months_observed': len(months), 'expected_payment_date': ms.isoformat()})
    if any(len({(d.year, d.month) for d, _ in v}) < 2 for v in groups.values()):
        notes.append('Some recurring outflows were seen in only one month; assumed to repeat monthly.')
    if not bank:
        notes.append('No bank history; lags default to 0 and no recurring outflows.')
    opening = 0.0
    for d, a, t in reversed(bank):
        b = _num(t.get('balance'))
        if b is not None:
            opening = b
            break
    tin = sum(x['amount'] for x in inflows)
    tout = sum(x['amount'] for x in outflows)
    net = round(tin - tout, 2)
    assumptions = [
        f'Customer collection lag vs due date: {lin} days (median of {len(lags_in)} matched payments).',
        f'Supplier payment lag vs due date: {lout} days (median of {len(lags_out)} matched payments).',
        'Overdue receivables (due before as_of_date) are assumed collected by end of target month, not earlier than its start.',
        'Not-yet-due items are included only if due date plus lag falls on or before target month end; earlier ones are placed at month start.',
        'Unpaid payables are paid at due date plus lag, never before as_of_date; earlier ones are placed at month start.',
        'Bank outflows not matching supplier invoices are treated as monthly recurring at their median amount.',
        'net_exposure_estimate = expected inflows - expected outflows for the target month; opening_balance is the last bank balance and is not included.']
    summary = (f'{tm}: expected inflows {tin:.2f}, outflows {tout:.2f}, net estimate {net:.2f} (opening balance {opening:.2f} not included). '
               f'{len(overdue)} overdue and {len(nyd)} not-yet-due receivables unpaid; {len(payables)} unpaid payables.')
    return {'overdue_receivables': overdue, 'not_yet_due_receivables': nyd, 'expected_inflows': inflows, 'expected_outflows': outflows,
            'unpaid_payables': payables, 'opening_balance': opening, 'net_exposure_estimate': net, 'assumptions': assumptions, 'notes': notes, 'summary': summary}

